  <script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/expr-eval@2/dist/bundle.min.js"></script>

  <style>
    /* ── Reset ───────────────────────────────────────────────────────────── */
    html,
    body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #fff;
    }

    /* ── Layout ──────────────────────────────────────────────────────────────
       body is a grid so #ui always takes a right-side column instead of covering
       the figure. The #container ResizeObserver then fires 'fig-resize', so
       setPlotFrame re-lays the figure out at its new size automatically.        */
    body {
      display: grid;
      grid-template-columns: 1fr;
      grid-template-rows: 1fr;
      grid-template-areas: "stage";
    }

    /* ── Figure mount point ──────────────────────────────────────────────── */
    #container {
      position: relative;
      grid-area: stage;
      min-width: 0;
      min-height: 0;
      overflow: hidden;
      box-sizing: border-box;
      padding: var(--figure-canvas-padding, 18px);
    }

    /* ── Control panel (mirrors base_scene_new.html #ui) ─────────────────── */
    #ui {
      position: absolute;
      left: 6px;
      bottom: 6px;
      display: flex;
      flex-direction: column;
      gap: 3px;
      font-family: sans-serif;
      font-size: 11px;
      max-width: 190px;
      max-height: 34%;
      overflow-y: auto;
      overflow-x: hidden;
      background: transparent;
      border: 0;
      box-shadow: none;
      opacity: 0.88;
      transform: none;
      transition: opacity 0.16s ease;
      z-index: 10;
    }

    #ui:hover,
    #ui:focus-within {
      opacity: 1;
    }

    #ui button {
      padding: 4px 10px;
      cursor: pointer;
      border: 1px solid #aaa;
      background: #f5f5f5;
      border-radius: 4px;
    }

    #ui button:hover {
      background: #e0e0e0;
    }

    #ui button.active {
      background: #c8e6ff;
      border-color: #5aabf0;
    }

    #ui label {
      display: flex;
      flex-direction: column;
      gap: 2px;
      text-shadow: 0 1px 2px #fff;
    }

    #ui input[type=range] {
      width: 86px;
    }

    /* ── Docked control panel ────────────────────────────────────────────────
       #ui is a grid cell with its own scroll, an opaque background, and roomier
       type. Generated code cannot switch it to an overlay or bottom strip.      */
    body[data-ui-layout="right"] {
      grid-template-columns: 1fr var(--ui-size, 320px);
      grid-template-rows: 1fr;
      grid-template-areas: "stage ui";
    }

    body[data-ui-layout="bottom"] {
      grid-template-columns: 1fr;
      grid-template-rows: 1fr var(--ui-size, 240px);
      grid-template-areas: "stage" "ui";
    }

    body[data-ui-layout="right"] #ui,
    body[data-ui-layout="bottom"] #ui {
      position: relative;
      grid-area: ui;
      left: auto;
      bottom: auto;
      max-width: none;
      max-height: none;
      min-width: 0;
      min-height: 0;
      width: auto;
      height: auto;
      gap: 6px;
      padding: 10px 12px;
      font-size: 12px;
      background: #fbfbfc;
      opacity: 1;
      overflow: auto;
      z-index: 1;
    }

    body[data-ui-layout="right"] #ui {
      border-left: 1px solid #dcdfe3;
    }

    body[data-ui-layout="bottom"] #ui {
      border-top: 1px solid #dcdfe3;
    }

    body[data-ui-layout="right"] #ui label,
    body[data-ui-layout="bottom"] #ui label {
      text-shadow: none;
    }

    body[data-ui-layout="right"] #ui input[type=range],
    body[data-ui-layout="bottom"] #ui input[type=range] {
      width: 100%;
    }

    body[data-ui-layout="right"] #ui textarea,
    body[data-ui-layout="bottom"] #ui textarea {
      width: 100%;
      box-sizing: border-box;
      min-height: 180px;
      resize: vertical;
      font-family: ui-monospace, Consolas, monospace;
      font-size: 11px;
      line-height: 1.45;
      tab-size: 2;
      border: 1px solid #cfd4da;
      border-radius: 4px;
      padding: 6px 8px;
    }

    body[data-ui-layout="bottom"] #ui textarea {
      min-height: 110px;
    }

    /* ── Inline equation parse errors ────────────────────────────────────── */
    .eq-err {
      color: #c00000;
      font-size: 10px;
      max-width: 180px;
      white-space: normal;
      text-shadow: 0 1px 2px #fff;
    }

    /* ── Hover tooltip ───────────────────────────────────────────────────── */
    #figTooltip {
      position: fixed;
      left: 0;
      top: 0;
      display: none;
      max-width: 210px;
      padding: 4px 8px;
      border-radius: 4px;
      background: rgba(0, 0, 0, 0.58);
      color: #fff;
      font: 11px/1.35 sans-serif;
      pointer-events: none;
      white-space: normal;
      z-index: 20;
    }
  </style>
</head>

<body data-ui-layout="right">
  <div id="container"></div>
  <div id="figTooltip"></div>
  <div id="ui">
    <!-- @FIGURE_UI_BEGIN -->
    <!-- @FIGURE_UI_END -->
  </div>

  <!-- Error overlay: shown if CDN fails or JS throws before rendering -->
  <div id="err-overlay" style="display:none;position:fixed;inset:0;background:#fff;z-index:999;
       flex-direction:column;align-items:center;justify-content:center;
       font-family:sans-serif;font-size:13px;color:#555;gap:10px;">
    <span id="err-msg">⚠ Figure failed to load</span>
    <button onclick="location.reload()" style="padding:5px 14px;border:1px solid #aaa;
        border-radius:5px;background:#f5f5f5;cursor:pointer;font-size:12px;">↻ Reload</button>
  </div>

  <script>
    /* ── Error overlay ───────────────────────────────────────────────────── */
    var _rendered = false;
    var _errOverlay = document.getElementById('err-overlay');
    window.__markRendered = function () { _rendered = true; _errOverlay.style.display = 'none'; };
    window.addEventListener('error', function (e) {
      if (!_rendered) {
        document.getElementById('err-msg').textContent = '⚠ ' + (e.message || 'Figure failed to load');
        _errOverlay.style.display = 'flex';
      }
    });
    setTimeout(function () { if (!_rendered) { _errOverlay.style.display = 'flex'; } }, 12000);

    /* ── Tooltip + popup helpers ─────────────────────────────────────────── */
    var _tooltip = document.getElementById('figTooltip');

    function showPopup(title, body) {
      window.parent.postMessage({ type: 'alex-popup', title: title, body: body }, '*');
    }
    function hidePopup() {
      window.parent.postMessage({ type: 'alex-popup', title: null }, '*');
    }
    function showTooltip(text, event) {
      if (!_tooltip || !text) return;
      _tooltip.textContent = text;
      _tooltip.style.display = 'block';
      _moveTooltip(event);
    }
    function _moveTooltip(event) {
      if (!_tooltip || _tooltip.style.display === 'none') return;
      var pad = 12;
      var x = Math.min(event.clientX + pad, window.innerWidth - (_tooltip.offsetWidth || 100) - pad);
      var y = Math.max(pad, event.clientY - (_tooltip.offsetHeight || 40) - pad);
      _tooltip.style.left = x + 'px';
      _tooltip.style.top = y + 'px';
    }
    function hideTooltip() {
      if (_tooltip) _tooltip.style.display = 'none';
    }
    document.addEventListener('mousemove', function (e) { _moveTooltip(e); });

    /* ── Resize event ────────────────────────────────────────────────────── */
    function _containerInnerSize() {
      var container = document.getElementById('container');
      var style = getComputedStyle(container);
      var padX = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
      var padY = (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
      return {
        width: Math.max(0, container.clientWidth - padX),
        height: Math.max(0, container.clientHeight - padY)
      };
    }

    new ResizeObserver(function () {
      var rect = _containerInnerSize();
      document.dispatchEvent(new CustomEvent('fig-resize', {
        detail: { width: rect.width, height: rect.height }
      }));
    }).observe(document.getElementById('container'));

    /* ── UI layout: keep controls in a right-side column ─────────────────────
     * setUiLayout(...) is retained only so older generated payloads do not
     * crash. It deliberately cannot change the side, overlay state, or size.
     * Docking resizes #container, which fires 'fig-resize', so setPlotFrame
     * re-lays the figure out at its new size instead of it being covered.
     */
    var _uiEl = document.getElementById('ui');

    function setUiLayout(mode, sizePx) {
      _autoUiLayout();
    }

    function _applyUiLayout(mode, sizePx) {
      var next = 'right';
      document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', sizePx + 'px');
    }

    // Generated figures do not get to decide panel placement: a stable right
    // column prevents controls from covering the figure and avoids layout jumps.
    var _autoUiTimer = 0;
    function _autoUiLayout() {
      var hasEditor = Boolean(_uiEl.querySelector('textarea'));
      var mode = 'right';
      var start = hasEditor ? 400 : 300;
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      var cap = Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      var size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', size + 'px');
      var guard = 0;
      function step() {
        if (guard++ > 6) return;
        if (_uiEl.scrollHeight <= _uiEl.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', size + 'px');
        requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    window.__autoUiLayout = _autoUiLayout;

    // Re-evaluate when generated code adds controls after first paint.
    new MutationObserver(function () {
      clearTimeout(_autoUiTimer);
      _autoUiTimer = setTimeout(_autoUiLayout, 0);
    }).observe(_uiEl, { childList: true, subtree: true });
    window.addEventListener('resize', function () { _autoUiLayout(); });

    /* ── Keyboard dismiss ────────────────────────────────────────────────── */
    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { hidePopup(); hideTooltip(); }
    });

    /* ── Expression parsing ──────────────────────────────────────────────── */
    /**
     * compileExpr(src, vars) → function(...args)
     *   src  : math source, e.g. 'sin(x) + 1', 'x^2', '2*x - 3'
     *   vars : variable names in argument order, e.g. ['x'] or ['x', 'y']
     * Throws an Error with a readable message on a syntax error or when the
     * source references a variable outside `vars`. Never returns a fallback.
     *
     * DUPLICATED (deliberately): base_scene_new.html has an equivalent ES-module
     * copy. Each scaffold is a standalone served HTML file and neither can
     * import the other, so behaviour changes must be made TWICE.
     * Keep this in sync with compileExpr in base_scene_new.html.
     */
    function compileExpr(src, vars) {
      if (!window.exprEval || !window.exprEval.Parser) {
        throw new Error('Expression parser unavailable (expr-eval CDN did not load)');
      }
      var names = (vars && vars.length) ? vars : ['x'];
      var parsed;
      try {
        parsed = new window.exprEval.Parser().parse(String(src));
      } catch (e) {
        throw new Error('Cannot parse "' + src + '": ' + ((e && e.message) ? e.message : e));
      }
      var used = parsed.variables();
      for (var i = 0; i < used.length; i++) {
        if (names.indexOf(used[i]) === -1) {
          throw new Error('Unknown variable "' + used[i] + '" (expected: ' + names.join(', ') + ')');
        }
      }
      return function () {
        var scope = {};
        for (var j = 0; j < names.length; j++) scope[names[j]] = arguments[j];
        var v;
        try { v = parsed.evaluate(scope); } catch (e) { return NaN; }
        return (typeof v === 'number') ? v : NaN;
      };
    }

    /* ── Plot frame: world → screen mapping (owns resize) ────────────────── */
    var _plotFrame = null;
    var _plots = [];
    var _plotResizeBound = false;

    /**
     * setPlotFrame({ xDomain, yDomain, margin, draw }) → frame
     * Establishes the world→screen mapping used by plotX / plotY and by every
     * plot helper. Call this once, before creating any plots. Registered plots
     * are re-sampled automatically on resize.
     */
    function setPlotFrame(opts) {
      opts = opts || {};
      var innerSize = _containerInnerSize();
      _plotFrame = {
        xDomain: opts.xDomain || [-5, 5],
        yDomain: opts.yDomain || [-5, 5],
        margin: (opts.margin == null) ? 24 : opts.margin,
        draw: opts.draw || SVG().addTo('#container').size('100%', '100%'),
        width: innerSize.width || 900,
        height: innerSize.height || 600
      };
      _recomputePlotScale();
      if (!_plotResizeBound) {
        _plotResizeBound = true;
        document.addEventListener('fig-resize', function (e) {
          if (!_plotFrame) return;
          _plotFrame.width = e.detail.width || _plotFrame.width;
          _plotFrame.height = e.detail.height || _plotFrame.height;
          _recomputePlotScale();
          for (var i = 0; i < _plots.length; i++) _plots[i].sample();
        });
      }
      return _plotFrame;
    }

    function _recomputePlotScale() {
      var f = _plotFrame, m = f.margin;
      f.sx = (f.width - 2 * m) / (f.xDomain[1] - f.xDomain[0]);
      f.sy = (f.height - 2 * m) / (f.yDomain[1] - f.yDomain[0]);
    }

    /** plotX(worldX) → screen px. Requires setPlotFrame() first. */
    function plotX(wx) {
      var f = _plotFrame;
      return f.margin + (wx - f.xDomain[0]) * f.sx;
    }

    /** plotY(worldY) → screen px (y axis flipped). Requires setPlotFrame() first. */
    function plotY(wy) {
      var f = _plotFrame;
      return f.height - f.margin - (wy - f.yDomain[0]) * f.sy;
    }

    function _registerPlot(handle) {
      _plots.push(handle);
      return handle;
    }

    function _unregisterPlot(handle) {
      var i = _plots.indexOf(handle);
      if (i >= 0) _plots.splice(i, 1);
    }

    function _resolveFn(value, vars) {
      if (typeof value === 'function') return value;
      return compileExpr(value, vars);
    }

    function _pointsAttr(points) {
      return points.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
    }

    /**
     * plotFunction(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain, samples=200,
     *           stroke='#1f77b4', width=2, dashed=false }
     * The drawn polyline is ALWAYS produced by sampling the compiled function
     * across `domain`. Non-finite samples split the line into segments instead
     * of drawing a spike.
     */
    function plotFunction(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'plot-' + id);
      var handle = {
        id: id,
        node: group,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setExpr: function (src) { this.fn = _resolveFn(src, vars); return this.sample(); },
        setFn: function (f) { this.fn = f; return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          if (!this.fn) return this;
          var segs = _sampleSegments(this.fn, this.domain, this.samples);
          for (var s = 0; s < segs.length; s++) {
            if (segs[s].length < 2) continue;
            var line = group.polyline(_pointsAttr(segs[s]))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4',
                width: opts.width || 2,
                linecap: 'round',
                linejoin: 'round'
              });
            if (opts.dashed) line.attr('stroke-dasharray', '5,4');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** Sample fn across domain, splitting at non-finite values. → [[ [px,py], … ], …] */
    function _sampleSegments(fn, domain, samples) {
      var a = domain[0], b = domain[1], n = Math.max(2, samples | 0);
      var segs = [], cur = [];
      for (var i = 0; i < n; i++) {
        var t = a + (b - a) * (i / (n - 1));
        var v;
        try { v = fn(t); } catch (e) { v = NaN; }
        if (typeof v === 'number' && isFinite(v)) {
          cur.push([plotX(t), plotY(v)]);
        } else if (cur.length) {
          segs.push(cur);
          cur = [];
        }
      }
      if (cur.length) segs.push(cur);
      return segs;
    }

    /**
     * fillBetween(id, opts) → handle
     *   opts: { lower, upper, variables=['x'], domain, samples=200,
     *           fill='#7fb3ff', opacity=0.45, stroke, strokeWidth=1 }
     * `lower` / `upper` may be expression strings or functions. The polygon is
     * built from EVERY sampled point on both boundaries, so a curved boundary
     * produces a curved region with no caller involvement.
     */
    function fillBetween(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'fill-' + id);
      var handle = {
        id: id,
        node: group,
        lower: opts.lower != null ? _resolveFn(opts.lower, vars) : function () { return 0; },
        upper: opts.upper != null ? _resolveFn(opts.upper, vars) : function () { return 0; },
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setLower: function (src) { this.lower = _resolveFn(src, vars); return this.sample(); },
        setUpper: function (src) { this.upper = _resolveFn(src, vars); return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.domain[0], b = this.domain[1], n = Math.max(2, this.samples | 0);
          var top = [], bottom = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var lo, hi;
            try { lo = this.lower(t); hi = this.upper(t); } catch (e) { lo = NaN; hi = NaN; }
            if (isFinite(lo) && isFinite(hi)) {
              top.push([plotX(t), plotY(hi)]);
              bottom.push([plotX(t), plotY(lo)]);
            }
          }
          if (top.length < 2) return this;
          bottom.reverse();
          var poly = group.polygon(_pointsAttr(top.concat(bottom)))
            .fill({
              color: opts.fill || '#7fb3ff',
              opacity: (opts.opacity == null) ? 0.45 : opts.opacity
            });
          if (opts.stroke) {
            poly.stroke({ color: opts.stroke, width: opts.strokeWidth || 1, linejoin: 'round' });
          } else {
            poly.stroke('none');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /**
     * plotParametric(id, opts) → handle
     *   opts: { x, y, variables=['t'], tDomain=[0,1], samples=200, stroke, width }
     */
    function plotParametric(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['t'];
      var group = _plotFrame.draw.group().attr('id', 'param-' + id);
      var handle = {
        id: id,
        node: group,
        fx: _resolveFn(opts.x, vars),
        fy: _resolveFn(opts.y, vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX: function (src) { this.fx = _resolveFn(src, vars); return this.sample(); },
        setY: function (src) { this.fy = _resolveFn(src, vars); return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.tDomain[0], b = this.tDomain[1], n = Math.max(2, this.samples | 0);
          var pts = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var vx, vy;
            try { vx = this.fx(t); vy = this.fy(t); } catch (e) { vx = NaN; vy = NaN; }
            if (isFinite(vx) && isFinite(vy)) pts.push([plotX(vx), plotY(vy)]);
          }
          if (pts.length >= 2) {
            group.polyline(_pointsAttr(pts))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4', width: opts.width || 2,
                linecap: 'round', linejoin: 'round'
              });
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** integrateSimpson(fn, a, b, n=200) → number. Composite Simpson's rule. */
    function integrateSimpson(fn, a, b, n) {
      n = Math.max(2, n || 200);
      if (n % 2) n++;
      var h = (b - a) / n, s = fn(a) + fn(b);
      for (var i = 1; i < n; i++) s += fn(a + i * h) * ((i % 2) ? 4 : 2);
      return (s * h) / 3;
    }

    /** findRoot(fn, a, b, tol=1e-9) → number | null. Bisection; null if no sign change. */
    function findRoot(fn, a, b, tol) {
      tol = tol || 1e-9;
      var fa = fn(a), fb = fn(b);
      if (!isFinite(fa) || !isFinite(fb) || fa * fb > 0) return null;
      for (var i = 0; i < 200; i++) {
        var m = (a + b) / 2, fm = fn(m);
        if (!isFinite(fm)) return null;
        if (Math.abs(fm) < tol || (b - a) / 2 < tol) return m;
        if (fa * fm < 0) { b = m; } else { a = m; fa = fm; }
      }
      return (a + b) / 2;
    }

    /* ── Equation input binding ──────────────────────────────────────────── */
    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs under one parent, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_new.html.
     */
    function _equationErrorSlot(input) {
      var parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        var slotId = 'eq-err-' + input.id;
        var byId = document.getElementById(slotId);
        if (byId) return byId;
        var namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      var existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      var span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → function(fn, src)
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify2dHtml catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_new.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') {
        return function (fn, src) { t(fn, src); };
      }
      if (t && t.handle) {
        var method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            'bindEquationInput("' + inputId + '"): target handle has no method "' + method +
            '". Use { handle, method: \'...\' } with a method the handle really has ' +
            '(plotFunction: setExpr, setFn; fillBetween: setLower, setUpper; ' +
            'plotParametric: setX, setY).'
          );
        }
        return function (fn) { t.handle[method](fn); };
      }
      if (t && typeof t.setFn === 'function') {
        return function (fn) { t.setFn(fn); };
      }
      throw new Error(
        'bindEquationInput("' + inputId + '"): this target cannot be driven — it is not a ' +
        'function and has no .setFn. Handles without .setFn (fillBetween, plotParametric) ' +
        'must be passed as { handle, method: \'setUpper\' } naming the setter to call.'
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     *   targets: a plot handle, a { handle, method } pair, a function(fn, src),
     *            or an array of any of those.
     *   opts   : { variables=['x'], onChange(fn, src) }
     *
     * On every valid edit, every target re-samples. On a parse error the last
     * good curve is kept and the message is shown inline — this function NEVER
     * substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_new.html.
     */
    function bindEquationInput(inputId, targets, opts) {
      opts = opts || {};
      var input = document.getElementById(inputId);
      if (!input) throw new Error('bindEquationInput: no element with id "' + inputId + '"');
      var vars = opts.variables || ['x'];
      var list = Array.isArray(targets) ? targets : [targets];
      var slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      var appliers = [];
      for (var k = 0; k < list.length; k++) appliers.push(_resolveEqTarget(inputId, list[k]));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          var fn = compileExpr(src, vars);
          for (var i = 0; i < appliers.length; i++) appliers[i](fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', function () { apply(input.value); });
      apply(input.value);
      return { apply: apply, input: input, errorSlot: slot };
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();
  </script>
</body>

</html>

GLOBALS (do not re-declare): showPopup(title,body), showTooltip(text,event), hideTooltip(), #container (mount target), window.__markRendered() (call once when drawn), 'fig-resize' CustomEvent on document, setUiLayout(mode, sizePx).
  #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel. Docking resizes #container and fires 'fig-resize', so setPlotFrame re-lays the figure out at its new size.

LIBRARY: Chart.js v4 (global: Chart). Append <canvas style="width:100%;height:100%;display:block"> to #container; options:{responsive:true,maintainAspectRatio:false}. window.__markRendered() immediately after new Chart().

VISUAL FIDELITY: the default state must be a faithful inline replacement for the source image.
- Color scheme: match every color exactly — axis lines, data series, fills, backgrounds
- Layout & proportions: same relative element positions, same axis ranges, same tick marks and gridlines
- Data shape: match curve trajectories, bar heights, scatter clusters, or node/edge layout — approximate magnitudes, not invented
- Labels & annotations: every label visible in the original must appear at the same position; use blueprint.reconstructionNotes for text and color coding
- Line styles: dashed vs solid, stroke weights, arrowhead presence — copy from the image
- The step-0 (default) state should look indistinguishable from the original at a glance, with no title bar or toolbar visible

TEXT PLACEMENT & READABILITY: faithful labels must still be readable.
- Treat every label, tick label, annotation, formula, and legend item as a collision-checked box, and check each one against lines, arrows, curves, points, nodes, tick marks, gridlines, controls, and other text before finalizing. Text must not sit on top of strokes or dense marks.
- If the source label is anchored to a busy line/arrow/node, keep the semantic anchor but move the text to the nearest open whitespace and connect it with a short leader line, pointer, or subtle dot.
- Draw text and label backgrounds after geometry so labels are on top. Over busy regions add a small white/translucent background rect, or a halo: text.attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' }).
- Do not add extra visible explanatory text inside the figure; use hover tooltips, click popups, and the scaffold narration panel for explanation.

SCALE SAFETY: figures may be stitched into chapters at different sizes.
- With Canvas, Chart.js custom drawing, or any pixel-based renderer, derive point radius, stroke width, arrowheads, ticks, label size, and annotation padding from min(plotWidth, plotHeight). Avoid large fixed pixel minimums such as Math.max(20, scaledRadius); use only small clamps that prevent invisibility.
- With SVG/viewBox geometry that already scales naturally, preserve that and avoid fixed px sizes that break it.
- If space is small, simplify or hide secondary labels instead of making marks oversized.

HOVER/CLICK (on user action only): hover → showTooltip(label,event)/hideTooltip(); cursor:pointer on interactive elements. Click → showPopup('Title','2–3 sentence explanation'). Animation: fill/opacity transitions only; no scale/translate/bounce.

CONTROLS (blueprint.interactions — render in UI section; add id="{id}Input" to every input). Each control's handler must teach the concept described in its "teaches" field:
  slider → <label>{label}: <output id="{id}Val">{default}</output><input id="{id}Input" type="range" min="{min}" max="{max}" step="{step}" value="{default}" oninput="document.getElementById('{id}Val').value=this.value;update_{id}(+this.value)"></label>  +  function update_{id}(v){}
  toggle → <label><input id="{id}Input" type="checkbox" onchange="toggle_{id}(this.checked)"> {label}</label>  +  function toggle_{id}(on){}
  button → <button onclick="trigger_{id}()">{label}</button>  +  function trigger_{id}(){}
  equation_input → one <label>{field.label} <input id="{field.id}Input" value="{field.default}"></label> per entry in the interaction's "fields"
  code_editor → a <textarea id="{id}Code"> plus sample tabs, an input for the interaction's "input", a Run button, and playback controls

DEMO STEPS (blueprint.demo_steps): if present and non-empty, build a step player in #ui:
  - A <p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"> showing the current step's narration
  - <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
  - Each step's .state sets matching interaction inputs to the specified values and calls their update functions
  - Step 0 is the default view (set on load); subsequent steps are one click away
  - Omit the player entirely if demo_steps is absent or empty

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: As a shallow one-hidden-layer network is given more hidden units, its fitted function gains enough piecewise-linear regions to pass through the training data AND track the true underlying function — capacity, not overfitting, is the limiting factor here.
KEY INSIGHT (what students should walk away understanding): Adding hidden units far beyond the number of training points makes the fitted function smoother and closer to the truth, not wilder — the danger of a small shallow network is not too little smoothing but too few linear regions to behave sensibly where there is no data.
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "As a shallow one-hidden-layer network is given more hidden units, its fitted function gains enough piecewise-linear regions to pass through the training data AND track the true underlying function — capacity, not overfitting, is the limiting factor here.",
  "figureType": "line_plot",
  "elements": [
    "3×2 grid of six panels labelled a) b) c) d) e) f)",
    "Panel titles: (a) no title / ground-truth only, (b) '6 hidden units', (c) '7 hidden units', (d) '8 hidden units', (e) '10 hidden units', (f) '50 hidden units'",
    "Shared x-axis labelled 'Input, x' with ticks 0.0, 0.5, 1.0 (bottom row panels carry the label)",
    "Shared y-axis labelled 'Output, y' with ticks -1.0, 0.0, 1.0 (left column panels carry the label)",
    "Black thick smooth curve: the true underlying function (one large peak near x≈0.25, trough near x≈0.75, rising slightly at x=1), identical in all six panels",
    "Salmon/terracotta filled circles: 7 training data points, identical positions in all panels — three on the rising left flank (x≈0.03, 0.12, 0.19), one below the trough (x≈0.81), two on the right flank (x≈0.92, 0.97)",
    "Pale teal/mint piecewise-linear curve: the fitted network output, present in panels b–f only, with a different number of visible kinks per panel",
    "Panel b fit: wildly diverging linear segments that shoot off the top and bottom of the axes between x≈0.3 and x≈0.8",
    "Panel c fit: overshooting peak above the true peak, deep dip below the axis near x≈0.72",
    "Panel d fit: peak slightly too high and too wide, dip too deep near x≈0.75",
    "Panel e fit: close to the true curve with a slight rightward shift on the falling flank",
    "Panel f fit: nearly indistinguishable from the true curve except for a mild bulge on the falling flank",
    "Axis frames drawn as plain black rectangles (box) with clipped curves",
    "Legend/key mapping: black = true function, teal = network fit, salmon dots = training data"
  ],
  "interactions": [
    {
      "id": "capacity",
      "type": "slider",
      "teaches": "That each extra hidden unit adds another linear region (another kink), and that the fit goes from violently unconstrained, to kinked but roughly right, to essentially exact as the number of regions exceeds what the data and function demand.",
      "label": "Hidden units:  — · 6 · 7 · 8 · 10 · 50",
      "range": [
        0,
        5,
        1
      ],
      "default": 0
    },
    {
      "id": "viewMode",
      "type": "toggle",
      "teaches": "That the jump from 6 to 50 units is not a small refinement but the difference between an uncontrolled and a near-perfect approximation, and that seeing all capacities side by side reveals a monotone trend rather than random variation.",
      "label": "View",
      "options": [
        "Single panel",
        "Compare 6 vs 50",
        "All six panels"
      ],
      "default": "Single panel"
    },
    {
      "id": "pickPanel",
      "type": "click",
      "teaches": "That any one capacity can be isolated and inspected against the seven training points, so the learner can check whether the fit actually interpolates the data or merely comes close."
    },
    {
      "id": "hoverPoint",
      "type": "hover",
      "teaches": "The vertical residual between the fitted curve and each training point at the current capacity, making 'fits the data' a measurable quantity rather than a visual impression.",
      "teaches_note": "hover over a salmon data point or a kink in the teal curve"
    }
  ],
  "demo_steps": [
    {
      "title": "The target and the data",
      "narration": "A smooth black true function and just seven salmon training points — this is everything the network gets to see. Notice the points are clustered on the two flanks and say almost nothing about the trough.",
      "state": {
        "capacity": 0,
        "viewMode": "Single panel"
      }
    },
    {
      "title": "6 hidden units: too few regions",
      "narration": "With six units the fit has only a handful of linear pieces, and it uses them to plunge far off the plot between the data clusters. It can hit the points but the function in between is nonsense.",
      "state": {
        "capacity": 1,
        "viewMode": "Single panel"
      }
    },
    {
      "title": "7 and 8 units: the shape appears",
      "narration": "One or two more units buy enough kinks to produce a peak and a trough in roughly the right places, though both overshoot the true curve badly.",
      "state": {
        "capacity": 3,
        "viewMode": "Single panel"
      }
    },
    {
      "title": "10 units: close, with a visible lag",
      "narration": "Ten units track the true function almost everywhere; the only obvious flaw is a slight rightward drift on the falling flank where no data constrain it.",
      "state": {
        "capacity": 4,
        "viewMode": "Single panel"
      }
    },
    {
      "title": "50 units: more parameters, better — not worse",
      "narration": "With fifty hidden units and still only seven data points the fit does not wiggle wildly; it hugs the true function. Extra capacity bought smoothness, not overfitting.",
      "state": {
        "capacity": 5,
        "viewMode": "Single panel"
      }
    },
    {
      "title": "6 versus 50 side by side",
      "narration": "Put the extremes next to each other: same data, same training procedure, radically different behaviour between the data points.",
      "state": {
        "capacity": 5,
        "viewMode": "Compare 6 vs 50"
      }
    },
    {
      "title": "The whole ladder",
      "narration": "All six panels at once show a clean monotone trend — error between the data points falls steadily as hidden units increase, with no sign of the classical overfitting bulge.",
      "state": {
        "capacity": 5,
        "viewMode": "All six panels"
      }
    }
  ],
  "keyInsight": "Adding hidden units far beyond the number of training points makes the fitted function smoother and closer to the truth, not wilder — the danger of a small shallow network is not too little smoothing but too few linear regions to behave sensibly where there is no data.",
  "reconstructionNotes": "Six equal panels in a 3-wide, 2-tall grid on white, each with a plain black box frame. Every panel plots the identical thick black true curve (a smooth wave: rises from y≈-0.3 at x=0 to a peak y≈0.6 near x=0.25, falls to a trough y≈-0.65 near x=0.75, then rises slightly to y≈-0.3 at x=1) and the identical seven salmon/terracotta filled circles (three on the left rising flank, one just below the trough near x≈0.81, two on the right flank near x≈0.92 and 0.97). Panel a has no fit and no title; panels b–f carry titles '6 / 7 / 8 / 10 / 50 hidden units' and add a pale mint-teal piecewise-linear fit of comparable thickness drawn on top of, but not obscuring, the black curve. The teal fit must always pass through or extremely near all seven salmon points; what changes with capacity is behaviour between them: at 6 units it shoots vertically off both the top and bottom of the axes in the data-free middle region; at 7 it overshoots the peak and dips below -1 near x≈0.72; at 8 it has a too-tall, too-wide peak and a too-deep trough; at 10 it is close with a rightward-shifted falling flank; at 50 it nearly coincides with the black curve with only a mild bulge on the falling flank. Axes: x ticks 0.0/0.5/1.0 labelled 'Input, x' on the bottom row, y ticks -1.0/0.0/1.0 labelled 'Output, y' on the left column; curves are clipped at the frame. Panel letters a)–f) sit at the upper-left outside each frame in bold. Colour key: black = true function, mint-teal = network fit, salmon = training data."
}

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:700;font-size:12px">Shallow net: hidden units vs. fit</span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;min-height:74px"></span>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;min-width:64px;text-align:center"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Hidden units: <output id="capacityVal">—</output>
  <input id="capacityInput" type="range" min="0" max="5" step="1" value="0"
         oninput="document.getElementById('capacityVal').value=UNIT_LABELS[+this.value];update_capacity(+this.value)">
</label>
<label>View
  <select id="viewModeInput" onchange="toggle_viewMode(this.value)">
    <option>Single panel</option>
    <option>Compare 6 vs 50</option>
    <option selected>All six panels</option>
  </select>
</label>
<span style="font-size:11px;line-height:1.7">
  <span style="display:inline-block;width:16px;height:3px;background:#000;vertical-align:middle"></span> true function<br>
  <span style="display:inline-block;width:16px;height:4px;background:#a7d8d0;vertical-align:middle"></span> network fit<br>
  <span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:#de8a68;vertical-align:middle"></span> training data
</span>
<span style="font-size:10px;color:#666;line-height:1.4">Hover a dot (residual) or a kink in the teal fit. Click a panel to isolate that capacity.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var TEAL = '#a7d8d0', SALMON = '#de8a68', SALMON_HL = '#c05f34', INK = '#000';
var FF = '"Helvetica Neue", Helvetica, Arial, sans-serif';
var UNIT_LABELS = ['—', '6', '7', '8', '10', '50'];

function clamp(lo, v, hi) { return Math.max(lo, Math.min(hi, v)); }

/* ---------- true underlying function ---------- */
function truth(x) {
  var p = 2 * Math.PI * (x - 0.26), q = 4 * Math.PI * (x - 0.26);
  return 0.6108 * Math.cos(p) + 0.1109 * Math.cos(q) - 0.1017;
}
var TRUTH_PTS = (function () {
  var a = [];
  for (var i = 0; i <= 260; i++) { var x = i / 260; a.push({ x: x, y: truth(x) }); }
  return a;
})();

/* ---------- training data (identical in every panel) ---------- */
var DATA = [
  { x: 0.035, y: -0.07 }, { x: 0.12, y: 0.19 }, { x: 0.195, y: 0.47 },
  { x: 0.81, y: -0.67 }, { x: 0.92, y: -0.45 }, { x: 0.97, y: -0.49 }
];

function V(a) { return a.map(function (p) { return { x: p[0], y: p[1] }; }); }

var FIT6 = V([[0, -0.10], [0.035, -0.07], [0.12, 0.19], [0.195, 0.47], [0.36, 1.35], [0.40, 1.20],
[0.565, -1.70], [0.73, -1.95], [0.81, -0.67], [0.875, -0.55], [0.92, -0.45], [0.97, -0.49], [1, -0.52]]);
var FIT7 = V([[0, -0.12], [0.035, -0.07], [0.12, 0.19], [0.195, 0.47], [0.285, 0.93], [0.455, 0.38],
[0.72, -1.15], [0.81, -0.67], [0.875, -0.50], [0.92, -0.45], [0.97, -0.49], [1, -0.52]]);
var FIT8 = V([[0, -0.13], [0.035, -0.07], [0.12, 0.19], [0.195, 0.47], [0.255, 0.72], [0.40, 0.50],
[0.615, -0.51], [0.755, -0.87], [0.81, -0.67], [0.885, -0.44], [0.92, -0.45], [0.97, -0.49], [1, -0.52]]);
var FIT10 = V([[0, -0.19], [0.035, -0.07], [0.12, 0.20], [0.195, 0.47], [0.26, 0.63], [0.335, 0.58],
[0.42, 0.32], [0.52, 0.00], [0.62, -0.38], [0.72, -0.60], [0.81, -0.67], [0.885, -0.45],
[0.92, -0.45], [0.97, -0.49], [1, -0.52]]);
var FIT50 = (function () {
  function base(x) { return truth(x) + 0.105 * Math.exp(-Math.pow((x - 0.44) / 0.13, 2)); }
  var pts = [], xs = [];
  for (var i = 0; i <= 60; i++) xs.push(i / 60);
  DATA.forEach(function (d) { xs.push(d.x); });
  xs.sort(function (a, b) { return a - b; });
  xs.forEach(function (x) {
    var y = base(x);
    DATA.forEach(function (d) {
      y += (d.y - base(d.x)) * Math.exp(-Math.pow((x - d.x) / 0.05, 2));
    });
    pts.push({ x: x, y: y });
  });
  return pts;
})();

var PANELS = [
  { letter: 'a)', title: '', fit: null, units: null },
  { letter: 'b)', title: '6 hidden units', fit: FIT6, units: 6 },
  { letter: 'c)', title: '7 hidden units', fit: FIT7, units: 7 },
  { letter: 'd)', title: '8 hidden units', fit: FIT8, units: 8 },
  { letter: 'e)', title: '10 hidden units', fit: FIT10, units: 10 },
  { letter: 'f)', title: '50 hidden units', fit: FIT50, units: 50 }
];

var POPUPS = [
  ['The target and the data',
    'The thick black curve is the function we want to learn; the salmon dots are the only observations the network ever sees. Notice the huge data-free gap between x≈0.2 and x≈0.8 — nothing in the training loss constrains the fit there.'],
  ['6 hidden units',
    'Six ReLU units give only a handful of linear regions. The fit still passes through every training point, yet between the clusters it shoots straight off the top and bottom of the plot. Too little capacity does not mean smooth behaviour.'],
  ['7 hidden units',
    'One extra unit buys one more kink: a peak and a trough now appear in roughly the right places, but both badly overshoot the true curve, and the fit still dives below the axis near x≈0.72.'],
  ['8 hidden units',
    'Eight units produce a recognisable version of the true shape — the peak is too tall and too wide and the trough too deep, but the function is no longer wild where there is no data.'],
  ['10 hidden units',
    'With ten units the fit tracks the black curve nearly everywhere. The remaining flaw is a rightward drift on the falling flank, exactly the region where no training point pins it down.'],
  ['50 hidden units',
    'Fifty hidden units and still only six data points: the fit does not wiggle wildly, it hugs the true function. Extra capacity bought smoothness and accuracy, not overfitting.']
];

/* ---------- state ---------- */
var figState = { capacity: 0, viewMode: 'All six panels' };
var highlightOn = false;
var _charts = [];

var container = document.getElementById('container');
var grid = document.createElement('div');
grid.style.cssText = 'width:100%;height:100%;display:grid;box-sizing:border-box;';
container.appendChild(grid);

function evalFit(pts, x) {
  if (!pts) return null;
  for (var i = 1; i < pts.length; i++) {
    if (x <= pts[i].x) {
      var a = pts[i - 1], b = pts[i], t = (b.x === a.x) ? 0 : (x - a.x) / (b.x - a.x);
      return a.y + t * (b.y - a.y);
    }
  }
  return pts[pts.length - 1].y;
}

/* ---------- plugins ---------- */
var framePlugin = {
  id: 'frame',
  afterDraw: function (chart) {
    var a = chart.chartArea, ctx = chart.ctx, o = chart.$opts;
    ctx.save();
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(1.2, o.lw * 0.55);
    ctx.strokeRect(a.left, a.top, a.right - a.left, a.bottom - a.top);
    ctx.restore();
  }
};

var overlayPlugin = {
  id: 'overlay',
  afterDatasetsDraw: function (chart) {
    var o = chart.$opts, ctx = chart.ctx, a = chart.chartArea;
    var X = function (v) { return chart.scales.x.getPixelForValue(v); };
    var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
    ctx.save();
    ctx.beginPath(); ctx.rect(a.left, a.top, a.right - a.left, a.bottom - a.top); ctx.clip();
    if (o.fit) {
      ctx.beginPath();
      o.fit.forEach(function (p, i) { i ? ctx.lineTo(X(p.x), Y(p.y)) : ctx.moveTo(X(p.x), Y(p.y)); });
      ctx.strokeStyle = TEAL; ctx.lineWidth = o.lw; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
      ctx.stroke();
    }
    // residual guide on hover
    if (o.fit && chart.$hl != null && chart.$hlType === 'data') {
      var d = DATA[chart.$hl], fy = evalFit(o.fit, d.x);
      ctx.save();
      ctx.setLineDash([3, 3]);
      ctx.strokeStyle = '#555'; ctx.lineWidth = Math.max(1, o.lw * 0.35);
      ctx.beginPath(); ctx.moveTo(X(d.x), Y(d.y)); ctx.lineTo(X(d.x), Y(fy)); ctx.stroke();
      ctx.restore();
    }
    DATA.forEach(function (d, i) {
      ctx.beginPath();
      ctx.arc(X(d.x), Y(d.y), o.pr, 0, 6.2832);
      ctx.fillStyle = (chart.$hlType === 'data' && chart.$hl === i) ? SALMON_HL : SALMON;
      ctx.fill();
    });
    if (o.fit && chart.$hlType === 'kink' && chart.$hl != null) {
      var k = o.fit[chart.$hl];
      ctx.beginPath(); ctx.arc(X(k.x), Y(k.y), o.pr * 0.85, 0, 6.2832);
      ctx.fillStyle = '#4fa79a'; ctx.fill();
    }
    ctx.restore();
  }
};

/* ---------- layout / rendering ---------- */
function visibleIdx() {
  if (figState.viewMode === 'All six panels') return [0, 1, 2, 3, 4, 5];
  if (figState.viewMode === 'Compare 6 vs 50') return [1, 5];
  return [figState.capacity];
}

function render() {
  _charts.forEach(function (c) { try { c.destroy(); } catch (e) { } });
  _charts = [];
  grid.innerHTML = '';

  var vis = visibleIdx();
  var all = figState.viewMode === 'All six panels';
  var cols = all ? 3 : (figState.viewMode === 'Compare 6 vs 50' ? 2 : 1);
  var rows = Math.ceil(vis.length / cols);
  var gapX = cols > 1 ? 16 : 4, gapY = rows > 1 ? 14 : 4;
  grid.style.gridTemplateColumns = 'repeat(' + cols + ',minmax(0,1fr))';
  grid.style.gridTemplateRows = 'repeat(' + rows + ',minmax(0,1fr))';
  grid.style.columnGap = gapX + 'px';
  grid.style.rowGap = gapY + 'px';

  var GW = grid.clientWidth || 600, GH = grid.clientHeight || 420;
  var pw = (GW - gapX * (cols - 1)) / cols;
  var ph = (GH - gapY * (rows - 1)) / rows;
  var s = Math.min(pw, ph);
  var fs = clamp(8, s * 0.072, 17);
  var titleFs = Math.min(fs * 1.22, pw / 8.5);
  var lw = clamp(1.3, s * 0.019, 5.5);
  var pr = clamp(2, s * 0.026, 9);
  var tl = clamp(3, s * 0.028, 8);
  var headH = Math.round(Math.max(fs, titleFs) * 1.55);

  vis.forEach(function (idx, k) {
    var P = PANELS[idx];
    var cell = document.createElement('div');
    cell.style.cssText = 'position:relative;min-width:0;min-height:0;display:flex;' +
      'flex-direction:column;cursor:pointer;border-radius:3px;';
    if (highlightOn && all && idx === figState.capacity) {
      cell.style.boxShadow = '0 0 0 2px #5aabf0';
    }

    var head = document.createElement('div');
    head.style.cssText = 'position:relative;flex:0 0 ' + headH + 'px;height:' + headH + 'px;';
    var letter = document.createElement('div');
    letter.style.cssText = 'position:absolute;left:0;top:0;font-family:' + FF +
      ';font-weight:700;font-size:' + (fs * 1.25).toFixed(1) + 'px;color:#000;line-height:1.1;';
    letter.textContent = P.letter;
    head.appendChild(letter);
    if (P.title) {
      var ttl = document.createElement('div');
      ttl.style.cssText = 'position:absolute;left:0;right:0;top:0;text-align:center;font-family:' + FF +
        ';font-size:' + titleFs.toFixed(1) + 'px;color:#000;line-height:1.15;white-space:nowrap;' +
        'overflow:hidden;text-overflow:ellipsis;';
      ttl.textContent = P.title;
      head.appendChild(ttl);
    }
    cell.appendChild(head);

    var wrap = document.createElement('div');
    wrap.style.cssText = 'position:relative;flex:1 1 auto;min-height:0;min-width:0;';
    var cv = document.createElement('canvas');
    cv.style.cssText = 'position:absolute;left:0;top:0;width:100%;height:100%;display:block;';
    wrap.appendChild(cv);
    cell.appendChild(wrap);
    grid.appendChild(cell);

    var showX = all ? (idx >= 3) : true;
    var showY = all ? (idx === 0 || idx === 3) : true;

    var chart = new Chart(cv.getContext('2d'), {
      type: 'line',
      data: {
        datasets: [{
          data: TRUTH_PTS, borderColor: INK, borderWidth: lw, pointRadius: 0,
          tension: 0, fill: false, borderCapStyle: 'round', borderJoinStyle: 'round'
        }]
      },
      options: {
        responsive: true, maintainAspectRatio: false, animation: false, resizeDelay: 0,
        layout: { padding: { top: Math.ceil(lw), right: Math.ceil(lw) + 2, left: 1, bottom: 1 } },
        plugins: { legend: { display: false }, tooltip: { enabled: false }, title: { display: false } },
        scales: {
          x: {
            type: 'linear', min: 0, max: 1,
            title: {
              display: showX, text: 'Input, x', color: '#000',
              font: { size: titleFs, family: FF }, padding: { top: 0, bottom: 0 }
            },
            ticks: {
              stepSize: 0.5, autoSkip: false, color: '#000', padding: 3,
              font: { size: fs, family: FF },
              callback: function (v) { return Number(v).toFixed(1); }
            },
            grid: {
              drawOnChartArea: false, drawTicks: true, tickLength: tl,
              tickColor: '#000', tickWidth: Math.max(1, lw * 0.45)
            },
            border: { display: false }
          },
          y: {
            type: 'linear', min: -1, max: 1,
            title: {
              display: showY, text: 'Output, y', color: '#000',
              font: { size: titleFs, family: FF }
            },
            ticks: {
              stepSize: 1, autoSkip: false, color: '#000', padding: 3,
              font: { size: fs, family: FF },
              callback: function (v) { return Number(v).toFixed(1); }
            },
            grid: {
              drawOnChartArea: false, drawTicks: true, tickLength: tl,
              tickColor: '#000', tickWidth: Math.max(1, lw * 0.45)
            },
            border: { display: false }
          }
        }
      },
      plugins: [overlayPlugin, framePlugin]
    });
    chart.$opts = { fit: P.fit, lw: lw, pr: pr };
    chart.$hl = null; chart.$hlType = null;
    chart.$panel = idx;
    _charts.push(chart);

    cv.addEventListener('mousemove', function (ev) { onMove(chart, cv, ev); });
    cv.addEventListener('mouseleave', function () {
      if (chart.$hl !== null) { chart.$hl = null; chart.$hlType = null; chart.draw(); }
      hideTooltip();
    });
    cell.addEventListener('click', function () { pickPanel(idx); });
  });

  window.__markRendered();
}

/* ---------- hover ---------- */
function onMove(chart, cv, ev) {
  var r = cv.getBoundingClientRect();
  var mx = ev.clientX - r.left, my = ev.clientY - r.top;
  var X = function (v) { return chart.scales.x.getPixelForValue(v); };
  var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
  var tol = Math.max(7, chart.$opts.pr + 5);
  var hit = null, type = null, best = 1e9;

  DATA.forEach(function (d, i) {
    var dx = mx - X(d.x), dy = my - Y(d.y), dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < tol && dist < best) { best = dist; hit = i; type = 'data'; }
  });
  var fit = chart.$opts.fit;
  if (hit === null && fit) {
    for (var i = 1; i < fit.length - 1; i++) {
      var p = fit[i];
      if (p.y > 1.02 || p.y < -1.02) continue;
      var dx2 = mx - X(p.x), dy2 = my - Y(p.y), dd = Math.sqrt(dx2 * dx2 + dy2 * dy2);
      if (dd < tol && dd < best) { best = dd; hit = i; type = 'kink'; }
    }
  }

  if (hit !== chart.$hl || type !== chart.$hlType) {
    chart.$hl = hit; chart.$hlType = type; chart.draw();
  }
  if (hit === null) { hideTooltip(); cv.style.cursor = 'pointer'; return; }
  cv.style.cursor = 'pointer';

  var txt;
  if (type === 'data') {
    var d = DATA[hit];
    txt = 'Training point  x = ' + d.x.toFixed(2) + ',  y = ' + d.y.toFixed(2);
    if (fit) {
      var fy = evalFit(fit, d.x);
      txt += '\nfit = ' + fy.toFixed(2) + '   residual = ' + (fy - d.y).toFixed(3);
    } else {
      txt += '  (panel a shows no fitted model)';
    }
  } else {
    var kp = fit[hit];
    txt = 'Kink in the fit at x = ' + kp.x.toFixed(2) +
      ' — boundary between two linear regions (one more unit ⇒ more kinks).';
  }
  showTooltip(txt, ev);
}

/* ---------- interactions ---------- */
function update_capacity(v) {
  figState.capacity = v | 0;
  highlightOn = true;
  render();
}
function toggle_viewMode(mode) {
  figState.viewMode = mode;
  render();
}
function pickPanel(idx) {
  figState.capacity = idx;
  highlightOn = true;
  var inp = document.getElementById('capacityInput');
  inp.value = idx;
  document.getElementById('capacityVal').value = UNIT_LABELS[idx];
  if (figState.viewMode !== 'Single panel') {
    figState.viewMode = 'Single panel';
    document.getElementById('viewModeInput').value = 'Single panel';
  }
  render();
  showPopup(POPUPS[idx][0], POPUPS[idx][1]);
}

