    state: { capacity: 5, viewMode: 'All six panels' }
  }
];
var stepIndex = 0;

function applyStep(i) {
  stepIndex = clamp(0, i, STEPS.length - 1);
  var st = STEPS[stepIndex];
  figState.capacity = st.state.capacity;
  figState.viewMode = st.state.viewMode;
  highlightOn = false;
  var cs = document.getElementById('capacityInput');
  cs.value = st.state.capacity;
  document.getElementById('capacityVal').value = UNIT_LABELS[st.state.capacity];
  document.getElementById('viewModeInput').value = st.state.viewMode;
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = st.label;
  render();
}
function nextStep() { applyStep(stepIndex + 1); }
function prevStep() { applyStep(stepIndex - 1); }

/* ---------- boot / resize ---------- */
var _rt = 0;
document.addEventListener('fig-resize', function () {
  clearTimeout(_rt);
  _rt = setTimeout(render, 70);
});

